    /// The three fire types, in upstream declaration order.
    pub const FIRE_TYPES: [FireType; 3] = [FireType::Normal, FireType::Soul, FireType::Light];

    /// The six lamp facings, in vanilla `Direction` order.
    pub const LAMP_FACINGS: [&str; 6] = ["down", "up", "north", "south", "west", "east"];

    /// The four wall-torch facings, in vanilla horizontal order.
    pub const WALL_FACINGS: [&str; 4] = ["north", "south", "west", "east"];

    /// Every lamp emits 15 (`ALLampSpec.LUMINANCE`).
    pub const LAMP_LIGHT: u8 = 15;

    /// The content declaration's scalar torch light; it is the default
    /// (`firetype=normal`) state's luminance, because a content block has one
    /// light value for every state.
    pub const TORCH_LIGHT: u8 = FireType::Normal.luminance();

    /// Lamp states: `facing` × `waterlogged`.
    pub const LAMP_STATES: usize = LAMP_FACINGS.len() * 2;

    /// Floor-torch states: `firetype` × `previous_firetype`.
    pub const TORCH_STATES: usize = FIRE_TYPES.len() * FIRE_TYPES.len();

    /// Wall-torch states: `facing` × `firetype` × `previous_firetype`.
    pub const WALL_TORCH_STATES: usize = WALL_FACINGS.len() * TORCH_STATES;

    /// The registry id of a lamp.
    pub fn lamp_id(base: &str) -> String {
        format!("additional_lights:al_lamp_{base}")
    }

    /// The registry id of a floor torch.
    pub fn torch_id(base: &str) -> String {
        format!("additional_lights:al_torch_{base}")
    }

    /// The registry id of a wall torch.
    pub fn wall_torch_id(base: &str) -> String {
        format!("additional_lights:al_wall_torch_{base}")
    }

    /// What a wall torch drops: its floor torch (`ALTorch_Wall.getDrops`).
    pub fn wall_torch_drop(base: &str) -> String {
        torch_id(base)
    }

    fn bases(torches: &[Torch]) -> BTreeSet<&'static str> {
        torches.iter().map(|t| t.base).collect()
    }

    #[test]
    fn lamps_are_the_24_upstream_materials_at_light_15() {
        assert_eq!(LAMPS.len(), 24);
        assert_eq!(LAMPS[0].base, "acacia_planks");
        assert_eq!(LAMPS[23].base, "warped_planks");
        for lamp in LAMPS {
            assert_eq!(lamp.light, LAMP_LIGHT, "{}", lamp.base);
            assert_eq!(lamp.light, 15, "{}", lamp.base);
        }
        let unique: BTreeSet<_> = LAMPS.iter().map(|l| l.base).collect();
        assert_eq!(unique.len(), LAMPS.len(), "duplicate lamp material");
    }

    #[test]
    fn floor_torches_are_the_28_upstream_materials() {
        assert_eq!(FLOOR_TORCHES.len(), 28);
        assert_eq!(FLOOR_TORCHES[0].base, "acacia_planks");
        assert_eq!(FLOOR_TORCHES[27].base, "blackstone");
        let unique: BTreeSet<_> = bases(&FLOOR_TORCHES);
        assert_eq!(
            unique.len(),
            FLOOR_TORCHES.len(),
            "duplicate torch material"
        );
    }

    #[test]
    fn wall_torches_pair_with_floor_torches() {
        assert_eq!(WALL_TORCHES.len(), FLOOR_TORCHES.len());
        assert_eq!(bases(&WALL_TORCHES), bases(&FLOOR_TORCHES));
    }

    #[test]
    fn fire_types_emit_upstream_levels() {
        assert_eq!(
            FIRE_TYPES.map(FireType::luminance),
            [14, 10, 15],
            "FireTypes.NORMAL/SOUL/LIGHT"
        );
        assert_eq!(
            FIRE_TYPES.map(FireType::name),
            ["normal", "soul", "light"],
            "serialized names"
        );
    }

    #[test]
    fn lamp_state_space_is_facing_times_waterlogged() {
        assert_eq!(LAMP_FACINGS.len(), 6);
        assert_eq!(LAMP_STATES, 12);
    }

    #[test]
    fn torch_state_space_is_firetype_times_previous() {
        assert_eq!(TORCH_STATES, 9);
    }

    #[test]
    fn wall_torch_state_space_adds_four_facings() {
        assert_eq!(WALL_FACINGS.len(), 4);
        assert_eq!(WALL_TORCH_STATES, 36);
    }

    #[test]
    fn content_scalar_light_is_the_default_state_light() {
        // `properties.light` is one number per block; upstream's default
        // `firetype` is `normal`, so that is the value a content torch can
        // declare. The soul/light delta is a recorded gap.
        assert_eq!(TORCH_LIGHT, 14);
        assert_eq!(TORCH_LIGHT, FireType::Normal.luminance());
    }

    #[test]
    fn wall_torch_drops_its_floor_torch() {
        assert_eq!(wall_torch_drop("stone"), "additional_lights:al_torch_stone");
        for torch in WALL_TORCHES {
            assert_eq!(
                wall_torch_drop(torch.base),
                torch_id(torch.base),
                "{}",
                torch.base
            );
        }
    }

    #[test]
    fn ids_are_unique_and_use_the_upstream_registry_names() {
        let mut ids = BTreeSet::new();
        for lamp in LAMPS {
            assert!(ids.insert(lamp_id(lamp.base)));
        }
        for torch in FLOOR_TORCHES {
            assert!(ids.insert(torch_id(torch.base)));
        }
        for torch in WALL_TORCHES {
            assert!(ids.insert(wall_torch_id(torch.base)));
        }
        assert_eq!(ids.len(), 80, "24 lamps + 28 floor + 28 wall torches");
        assert!(ids.contains("additional_lights:al_lamp_stone"));
        assert!(ids.contains("additional_lights:al_torch_quartz_block"));
        assert!(ids.contains("additional_lights:al_wall_torch_blackstone"));
    }
